cssRules:
.empty-canvas {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  border: 1px dashed rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  text-align: center;
  background: rgba(255, 255, 255, 0.015);
}
.empty-icon {
  width: 44px;
  height: 44px;
  color: #71717a;
  margin-bottom: 12px;
}
.empty-heading {
  font-size: 14px;
  font-weight: 600;
  color: #e4e4e7;
  margin-bottom: 6px;
}
.empty-desc {
  font-size: 12px;
  color: #a1a1aa;
  max-width: 320px;
  line-height: 1.5;
  margin-bottom: 16px;
}
.empty-action {
  font-size: 12px;
  padding: 6px 14px;
  background: #27272a;
  color: #f4f4f5;
  border: 1px solid #3f3f46;
  border-radius: 6px;
  cursor: pointer;
}
